	@Test
	void boundedSpillProducesEveryGroupAndReleasesItsLedger() throws Exception {
		String property = NativeCountGroupStore.MAX_BYTES_PROPERTY;
		String previous = System.setProperty(property, "4096");
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(8L << 20, 8L << 20);
		try (var ledger = manager.openQuery()) {
			int predicates = 64;
			Fixture fixture = new Fixture(predicates, 3L, 1L);
			Map<String, Long> actual = new HashMap<>();
			LmdbProjectedPredicateJoin.Statistics stats = fixture.multiply(orderedPairs(actual), null, -1, ledger);
			Map<String, Long> expected = new HashMap<>();
			for (long left = 11; left < 11 + predicates; left++) {
				for (long right = left + 1; right < 11 + predicates; right++) {
					expected.put(left + ":" + right, 1L);
				}
			}
			assertEquals(expected, actual);
			assertEquals("bounded-spill", stats.accumulator());
			assertEquals(expected.size(), stats.groups());
		} finally {
			if (previous == null) {
				System.clearProperty(property);
			} else {
				System.setProperty(property, previous);
			}
		}
		assertEquals(0L, manager.usedBytes());
	}

